local M = {}

local mt = {}

local function unwrap(x)
  if type(x) == 'table' and getmetatable(x) == mt then
    return x.value
  end
  return tonumber(x) or 0
end

local function wrap(x)
  return setmetatable({ value = unwrap(x) }, mt)
end

function M.new(x)
  return wrap(x)
end

function M.trunc(x)
  local n = unwrap(x)
  if n >= 0 then
    return wrap(math.floor(n))
  end
  return wrap(math.ceil(n))
end

function M.abs(x)
  return wrap(math.abs(unwrap(x)))
end

function M.tonumber(x)
  return unwrap(x)
end

function M.digits(_)
  return nil
end

mt.__add = function(a, b)
  return wrap(unwrap(a) + unwrap(b))
end

mt.__sub = function(a, b)
  return wrap(unwrap(a) - unwrap(b))
end

mt.__mul = function(a, b)
  return wrap(unwrap(a) * unwrap(b))
end

mt.__div = function(a, b)
  return wrap(unwrap(a) / unwrap(b))
end

mt.__mod = function(a, b)
  return wrap(unwrap(a) % unwrap(b))
end

mt.__pow = function(a, b)
  return wrap(unwrap(a) ^ unwrap(b))
end

mt.__unm = function(a)
  return wrap(-unwrap(a))
end

mt.__eq = function(a, b)
  return unwrap(a) == unwrap(b)
end

mt.__lt = function(a, b)
  return unwrap(a) < unwrap(b)
end

mt.__le = function(a, b)
  return unwrap(a) <= unwrap(b)
end

mt.__tostring = function(a)
  return tostring(unwrap(a))
end

return M

-- [nfnl] fnl/metabuffer/buffer/info.fnl
local base_buffer_mod = require("metabuffer.buffer.base")
local M = {}
local function apply_info_buffer_opts_21(buf)
  return base_buffer_mod["apply-buffer-opts!"](buf, {buftype = "nofile", bufhidden = "wipe", filetype = "", modifiable = false, swapfile = false})
end
M["prepare-buffer!"] = function(buf)
  return apply_info_buffer_opts_21(buf)
end
M.new = function(buf)
  return base_buffer_mod["register-managed-buffer!"](buf, "info", "[Metabuffer Info]", {buftype = "nofile", bufhidden = "wipe", filetype = "", modifiable = false, swapfile = false}, nil)
end
return M

-- [nfnl] fnl/metabuffer/metaline.fnl
local M = {}
M.new = function(line, meta)
  return {line = line, meta = meta}
end
return M

-- [nfnl] fnl/nfnl/notify.fnl
local _local_1_ = require("metabuffer.nfnl.module")
local autoload = _local_1_.autoload
local core = autoload("metabuffer.nfnl.core")
local function notify(level, ...)
  return vim.api.nvim_notify(core.str(...), level, {})
end
local function debug(...)
  return notify(vim.log.levels.DEBUG, ...)
end
local function error(...)
  return notify(vim.log.levels.ERROR, ...)
end
local function info(...)
  return notify(vim.log.levels.INFO, ...)
end
local function trace(...)
  return notify(vim.log.levels.TRACE, ...)
end
local function warn(...)
  return notify(vim.log.levels.WARN, ...)
end
return {debug = debug, error = error, info = info, trace = trace, warn = warn}

